class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        long long ans = 0;
        vector<unordered_map<int,int>> dp(n);
        if ((nums[0] | k) == nums[0]) {
            dp[0][nums[0]]++;
        }
        ans += dp[0][k];
        for (int i = 1; i < n; i++) {
            for (auto [key, value] : dp[i-1]) {
                if (((nums[i]&key) | k) == (nums[i]&key)) {
                    dp[i][nums[i]&key] += value;
                }
            }
            dp[i][nums[i]]++;
            ans += dp[i][k];
        }
        return ans;
    }
};

