class Solution {
public:
    int mx_bits = 0;
    long long is_valid(int mid , int ind , vector<vector<int>> &hsh){
        int len = mid - ind + 1;
        long long cal = 0;
        for(int j = 0 ; j < 32 ; j++){
            int tum = hsh[mid][j];
            if(ind) tum -= hsh[ind - 1][j];
            if(tum == len) cal |= (1 << j);
        }
        return cal;
    }
    int longest(int ind , int k , vector<vector<int>> &hsh){
        int high = hsh.size() - 1 , low = ind;
        while(high - low > 1){
            int mid = (high + low) >> 1;
            long long cal = is_valid(mid ,ind, hsh);
            if(cal == k) low = mid;
            else{
                if(cal > k) low = mid;
                else high = mid;
            }
        }
        long long cal = is_valid(high ,ind, hsh);
        if(cal == k) return high;
        cal = is_valid(low , ind , hsh);
        if(cal == k) return low;
        return -1;
    }

    int closest(int ind , int k, vector<vector<int>> &hsh){
        int high = hsh.size() - 1 , low = ind;
        while(high - low > 1){
            int mid = (high + low) >> 1;
            long long cal = is_valid(mid ,ind, hsh);
            if(cal == k) high = mid;
            else{
                if(cal > k) low = mid;
                else high = mid;
            }
        }
        long long cal = is_valid(low ,ind, hsh);
        if(cal == k) return low;
        cal = is_valid(high , ind , hsh);
        if(cal == k) return high;
        return -1;
    }

    long long countSubarrays(vector<int>& v, int k) {
        vector<vector<int>> bits;
        vector<int> hsh(32 , 0);
        mx_bits = 0;
        for(int i = 0; i < v.size() ; i++){
            for(int j = 0 ; j < 32 ; j++){
                if(v[i] & (1 << j)){
                    hsh[j]++;
                    mx_bits = j;
                }
            }
            bits.push_back(hsh);
        }
        long long ans = 0;
        for(int i = 0 ; i < v.size() ; i++){
            int r = longest(i , k , bits);
            if(r == -1) continue;
            int l = closest(i , k , bits);
            ans += r + 1LL - l;
        }

        return ans;
    }
};

