class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        if(x==1){
            x=0;
            build_LOG(1e5+10);
        }
        int n = nums.size();
        SparseTable<int>s(n);
        s.build(nums);
        long long int ans = 0;
        for (int i = 0; i < n; ++i){
            int l=i,r=n-1;
            int h = -1;
            while(l<=r){
                int mid = l+(r-l)/2;
                int AND = s.query1(i,mid);
                if(AND <= k){
                    r=mid-1;
                    h=mid;
                }else {
                    l=mid+1;
                }
            }
            if(h==-1)continue;
            int AND = s.query1(i,h);
            if(AND==k){
                int start = h;
                l=h,r=n-1;
                while(l<=r){
                    int mid = l+(r-l)/2;
                    int AND2 = s.query1(i,mid);
                    if(AND2 >= k){
                        l=mid+1;
                        h=mid;
                    }else {
                        r=mid-1;
                    }
                }
                if(s.query1(i,h) ==k && s.query1(i,start)==k)ans+=(h-start+1);
            }
        }
        return ans;

    }
};

