class Node {
    public:
    long long val;

    Node() {
        val = (1ll<<31)-1;
    }

    Node(long long v) {
        val = v;
    }
};

class Sg {
    public:
    ll size;
    vector<Node> values;
    Node merge(Node l,Node r) {
        return Node(l.val & r.val);
    }

    Node single(ll v) {
        return Node(v);
    }
    void init(ll n) {
        size = 1;
        while(size < n) size *= 2; 
        values.resize(2*size -1); 
    }
    void build(vector<int> &a,ll x,ll lx,ll rx) {
        if(rx-lx == 1) {
            if(lx < int(a.size())) {
                values[x] = single(a[lx]);
            }
            return; 
        }

        ll m = (lx+rx)/2;
        build(a,2*x +1,lx,m);
        build(a,2*x +2,m,rx);
        values[x] = merge(values[2*x +1],values[2*x +2]);
    }

    void build(vector<int> &a) {
        build(a,0,0,size);
    }

    void set(ll i,ll v,ll x,ll lx,ll rx) {
        if(rx-lx == 1) {
            values[x] = single(v);
            return;
        }

        ll m = (lx+rx)/2;
        if(i < m) {
            set(i,v,2*x +1,lx,m);
        }
        else {
            set(i,v,2*x +2,m,rx);
        }
        values[x] = merge(values[2*x+1],values[2*x+2]);
    }

    void set(ll i,ll v) {
        set(i,v,0,0,size);
    }

    Node calc(ll l,ll r,ll x,ll lx,ll rx) {
        if(lx >= r || l >= rx) return  Node();
        if(lx >= l && rx <= r) return values[x];
        ll m = (lx+rx)/2;
        Node s1 = calc(l,r,2*x+1,lx,m);
        Node s2 = calc(l,r,2*x+2,m,rx);
        return merge(s1,s2);
    }   

    Node sum(ll l,ll r) {
        return calc(l,r+1,0,0,size);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& arr, int k) {
        int n = arr.size();

        Sg st;
        st.init(n);
        st.build(arr);

        long long ans = 0;
        auto fMin = [&](int i) -> ll {
                int minIndex = n;
                int l = i;
                int r = n-1;
                while(l <= r){
                    int mid = l + (r-l)/2;
                    int res = st.sum(i, mid).val;
                    if(res == k) {
                        minIndex = mid;
                        r = mid-1;
                    }
                    else if(res < k) r = mid-1;
                    else l = mid+1;
                }
                return minIndex;
        };
        auto fMax = [&](int i) -> ll {
                int maxIndex = -1;
                int l = i;
                int r = n-1;
                while(l <= r){
                    int mid = l + (r-l)/2;
                    int res = st.sum(i, mid).val;
                    if(res == k) {
                        maxIndex = mid;
                        l = mid+1;
                    }
                    else if(res < k) r = mid-1;
                    else l = mid+1;
                }
                return maxIndex;
            };
        for(int i=0; i<n; ++i) {
            int mni = fMin(i);
            int mxi = fMax(i);
            if(mni != n && mxi != -1) ans += (mxi - mni + 1);
        }
        return ans;
    }
};

class Solution {
