    class SegmentTree {
private:
    vector<int> tree;
    int n;

    void buildTree(vector<int>& nums, int node, int start, int end) {
        if (start == end) {
            tree[node] = nums[start];
        } else {
            int mid = (start + end) / 2;
            int leftChild = 2 * node + 1;
            int rightChild = 2 * node + 2;
            buildTree(nums, leftChild, start, mid);
            buildTree(nums, rightChild, mid + 1, end);
            tree[node] = tree[leftChild] & tree[rightChild];
        }
    }

    int query(int node, int start, int end, int L, int R) {
        if (R < start || end < L) {
            return -1;  // Return all bits set (since AND with all bits set is neutral)
        }
        if (L <= start && end <= R) {
            return tree[node];
        }
        int mid = (start + end) / 2;
        int leftChild = 2 * node + 1;
        int rightChild = 2 * node + 2;
        int leftResult = query(leftChild, start, mid, L, R);
        int rightResult = query(rightChild, mid + 1, end, L, R);
        if (leftResult == -1) return rightResult;
        if (rightResult == -1) return leftResult;
        return leftResult & rightResult;
    }

public:
