            num /= 2;
        }

        return;
    }

public:
    long long countSubarrays(vector<int>& nums, int k) {
        vector<int> last_zero(31, -1);
        int len = nums.size();
        long long ans = 0;
        vector<int> k_v(31);
        getVector(k, k_v);
        vector<int> cur_v(31);
        int min_idx, max_idx;

        for (int i = 0; i < len; i++) {
            getVector(nums[i], cur_v);
            min_idx = 0;
            max_idx = i;
            bool ok = true;

            for (int j = 0; j < 31; j++) {
                if (cur_v[j] == 0) {
                    last_zero[j] = i;
                    if (k_v[j] == 1) {
                        ok = false;
                    }
                    continue;
                }

                if (k_v[j] == 1) { // k - 1, cur - 1
                    min_idx = max(min_idx, last_zero[j] + 1);
                    continue;
                }

                // k - 0, cur - 1
                if (last_zero[j] == -1) {
                    ok = false;
                    continue;
                }

                max_idx = min(max_idx, last_zero[j]);
            }

            if (ok and max_idx >= min_idx) {
                ans += (long long) (max_idx - min_idx + 1); 
            }
        }

        return ans;
    }
};

