    int add(int val, vector<int>& bit){
        for(int i=0;i<31;i++){
            if(!(val>>i & 1)) bit[i]++;
        }

        int ans = INT_MAX;
        for(int i=0;i<31;i++){
            if(bit[i]){
                int temp = 1<<i;
                temp = ~temp;
                ans = ans & temp;
            }
        }

        return ans;
    }

    int remove(int val, vector<int>& bit){
        for(int i=0;i<31;i++){
            if(!(val>>i & 1)) bit[i]--;
        }

        int ans = INT_MAX;
        for(int i=0;i<31;i++){
            if(bit[i]){
                int temp = 1<<i;
                temp = ~temp;
                ans = ans & temp;
            }
        }

        return ans;
    }

