class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int size = nums.size();
        long long total = 0;
        unordered_map<long long, long long> previousResults;
        for (int index = 0; index < size; ++index) {
            total += countSubarraysWithTarget(nums, index, k, previousResults);
            updatePreviousResults(previousResults, nums[index]);
        }
        return total;
    }
private:
    long long countSubarraysWithTarget(vector<int>& nums, int index, int k, unordered_map<long long, long long>& previousResults) {
        long long total = 0;
        long long target = k;
        total += countExactMatches(nums[index], target);
        unordered_map<long long, long long> currentResults;
        currentResults[nums[index]] = 1;
        for (auto& [value, frequency] : previousResults) {
            long long newAndResult = value & nums[index];
            total += countMatches(newAndResult, target, frequency);
            currentResults[newAndResult] += frequency;
        }
        previousResults.swap(currentResults);
        return total;
    }
    void updatePreviousResults(unordered_map<long long, long long>& previousResults, int num) {
        unordered_map<long long, long long> newResults;
        for (auto& [value, frequency] : previousResults) {
            long long newAndResult = value & num;
            newResults[newAndResult] += frequency;
        }
        previousResults.swap(newResults);
    }
    long long countExactMatches(long long num, long long target) {
        return (num == target) ? 1 : 0;
    }
    long long countMatches(long long newAndResult, long long target, long long frequency) {
        return (newAndResult == target) ? frequency : 0;
    }
};

