class BitwiseAND {
    vector<vector<int>> st;
    vector<int> log;

public:
    BitwiseAND(const vector<int>& arr) {
        int n = arr.size();
        int K = log2(n) + 1;

        st.assign(n, vector<int>(K));
        log.assign(n + 1, 0);

        for (int i = 2; i <= n; i++)
            log[i] = log[i / 2] + 1;

        for (int i = 0; i < n; i++)
            st[i][0] = arr[i];

        for (int j = 1; j < K; j++) {
            for (int i = 0; i + (1 << j) <= n; i++) {
                st[i][j] = st[i][j - 1] & st[i + (1 << (j - 1))][j - 1];
            }
        }
    }

    int query(int L, int R) {
        int j = log[R - L + 1];
        return st[L][j] & st[R - (1 << j) + 1][j];
    }
};

