        ll l = i, r = n - 1, l1 = -1, r1 = -1;
        while (l <= r)
        {
            ll mid = (l + (r - l) / 2);
            if (b.query(i, mid) >= k)
            {
                l1 = mid;
                l = mid + 1;
            }
            else
            {
                r = mid - 1;
            }
        }
        l = i, r = n - 1;
        while (l <= r)
        {
            ll mid = (l + (r - l) / 2);
            if (b.query(i, mid) <= k)
            {
                r1 = mid;
                r = mid - 1;
            }
            else
            {
                l = mid + 1;
            }
        }
        swap(l1, r1);
        // debug(l1, r1, i);
        if (l1 != -1 && r1 != -1 && b.query(i, l1) == b.query(i, r1) && b.query(i, l1) == k)
        {
            // debug(l1, r1);
            ans += (r1 - l1 + 1);
        }
    }
    // debug(b.query(1, 3));
    return ans;
}
};

