class DSU {
private:
    int sz;
    vector<int> root, rank;
public:
    DSU(int sz){
        this->sz = sz;
        root.resize(sz);
        rank.resize(sz);
        for(int i = 0; i < sz; i++){
            root[i] = i;
            rank[i] = 1;
        }
    }

    int find(int x){
        if(root[x] == x) return x;
        return root[x] = find(root[x]);
    }

    bool unionSet(int x, int y){
        int rootX = find(x);
        int rootY = find(y);
        if(rootX == rootY)
            return false;
        if(rank[rootX] > rank[rootY])
            root[rootY] = rootX;
        else if(rank[rootX] < rank[rootY])
            root[rootX] = rootY;
        else{
            root[rootY] = rootX;
            rank[rootX]++;
        }
        return true;
    }

    void reset() {
        for(int i = 0; i < sz; i++){
            root[i] = i;
            rank[i] = 1;
        }
    }
};


class TreeAncestor {
    public:
    vector<vector<int>> vec;
    vector<int> depth;
    int h = 18;
    int n;
    TreeAncestor(int _n, vector<int>& parent) {
        n = _n;
        depth.resize(n,0);
        vec.resize(h,vector<int>(n+1,-1));
        for(int i=0;i<n;i++){
            vec[0][i] = parent[i];
        }
        for(int i=1;i<h;i++){
            for(int j=0;j<n;j++){
                if(vec[i-1][j] != -1)
                    vec[i][j] = vec[i-1][vec[i-1][j]];
            }
        }
    }

    int getKthAncestor(int node, int k) {
        for(int i=0;i<h;i++){
            if(k&(1<<i)){
                node = vec[i][node];
                if(node == -1){
                    return -1;
                }
            }
        }
        return node;
    }
    int lca(int a, int b)
    {
        if(depth[a] < depth[b])
            swap(a, b);

        int diff = depth[a] - depth[b];
        for(int i = 0; i < 16; i++)
            if(diff & (1 << i))
                a = vec[a][i];

        if(a == b)
            return a;

        for(int i = 15; i >= 0; i--)
        {
            if(vec[a][i] != vec[b][i])
            {
                a = vec[a][i];
                b = vec[b][i];
            }
        }

        return vec[a][0];
    }
    void dfs(int src, int paren,vector<vector<int>> &g)
    {
        for(auto x : g[src])
        {
            if(x == paren)
                continue;
            depth[x] = depth[src] + 1;
            dfs(x, src,g);
        }
    }
};

