class SegmentTree {
private:
    int n;
    vector<int> tree;

public:
    SegmentTree(vector<int>& nums) {
        n = nums.size();
        tree.resize(2 * n);
        build(nums);
    }

    void build(vector<int>& nums) {
        for (int i = 0; i < n; ++i) {
            tree[n + i] = nums[i];
        }
        for (int i = n - 1; i > 0; --i) {
            tree[i] = tree[2 * i] & tree[2 * i + 1];
        }
    }

    int query(int l, int r) {
        l += n;
        r += n;
        int res = INT_MAX;
        while (l < r) {
            if (l % 2 == 1) {
                res &= tree[l++];
            }
            if (r % 2 == 1) {
                res &= tree[--r];
            }
            l /= 2;
            r /= 2;
        }
        return res;
    }
};
