int query(int node,int st,int e,int l,int r){
    if(st>=l && e<=r) return tree[node];
    if(r<st || l>e) return INT_MAX;
    int mid=(st+e)/2;
    return query(node*2+1,st,mid,l,r)&query(node*2+2,mid+1,e,l,r);
}
