class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        int n = a.size();
        vector<int> last0(32, -1);
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 31; j++) {
                bool is_set = a[i] & (1 << j);
                if (!is_set) last0[j] = i;
            }
            int mini1 = i + 1;
            int maxi0 = 0;
            for (int j = 0; j < 31; j++) {
                if (k & (1 << j)) {
                    mini1 = min(mini1, i - last0[j]);
                } else {
                    maxi0 = max(maxi0, i - last0[j] + 1);
                }
            }
            if (mini1 >= maxi0) ans += 1LL * mini1 - maxi0 + 1;
        }
        return ans;
    }
};

static constexpr unsigned bits = 31;
class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        const unsigned n = nums.size();
        vector<array<unsigned, bits>> cntbits(n + 1);
        array<unsigned, bits> cnt {};
        for (unsigned i = 0; i < n; ++i) {
            auto num = nums[i];
            for (unsigned bit = 0; num; ++bit, num >>= 1)
                cnt[bit] += num & 1;
            cntbits[i + 1] = cnt;
        }
        auto andsum = [&](auto l, auto r) { // nums[l] & ... & nums[r]
            int ret = 0;
            for (unsigned bit = 0, bm = 1; bit < bits; ++bit, bm <<= 1)
                if (cntbits[r + 1][bit] - cntbits[l][bit] == r - l + 1)
                    ret |= bm;
            return ret;
        };
        auto countbits = [k](auto v) {
            unsigned missing = 0;
            unsigned extra = 0;
            for (unsigned i = 0, mask = 1; i < bits; ++i, mask <<= 1) {
                if ((v & mask) && !(k & mask))
                    ++extra;
                if (!(v & mask) && (k & mask))
                    ++missing;
            }
            return pair { missing, extra };
        };
        long long ret = 0;
        for (unsigned i = 0; i < n; ++i) {
            //assert(andsum(i, i) == nums[i]);
            {
                auto [miss, ex] = countbits(nums[i]);
                if (miss)
                    continue;
            }
            {
                auto [miss, ex] = countbits(andsum(0, i));
                if (ex)
                    continue;
            }
            unsigned a;
            // look for first index such that andsum(a, i) does not have missing bits
            {
                unsigned lo = 0;
                unsigned hi = i;
                while(lo < hi) {
                    unsigned mid = lo + (hi - lo)/2;
                    auto s = andsum(mid, i);
                    auto [miss, ex] = countbits(s);
                    if (miss)
                        lo = mid + 1;
                    else
                        hi = mid;
                }
                a = lo;
            }
            {
                auto [miss, ex] = countbits(andsum(a, i));
                if (ex)
                    continue;
            }
            // look for last index that has no extra bits
            unsigned b;
            {
                unsigned lo = a;
                unsigned hi = i;
                while(lo < hi) {
                    unsigned mid = lo + (hi - lo + 1)/2;
                    auto s = andsum(mid, i);
                    auto [miss, ex] = countbits(s);
                    if (ex)
                        hi = mid - 1;
                    else
                        lo = mid;
                }
                b = lo;
            }
            ret += b - a + 1;
        }
        return ret;        
    }
};

