    class ST {

        int leftmost;

        int rightmost;

        ST lchild;

        ST rchild;

        int max,lmax,rmax;


        public ST(int leftmost, int rightmost, int[] a) {

            this.leftmost = leftmost;

            this.rightmost = rightmost;

            if (leftmost == rightmost) {

                // leaf

                max = lmax = rmax = a[leftmost];

            } else {

                // 2 children

                int mid = (leftmost + rightmost) / 2;

                // (l,mid) (mid+1,r)

                lchild = new ST(leftmost, mid, a);

                rchild = new ST(mid + 1, rightmost, a);

                recalc();

            }

        }

        public void recalc() {

            max= Math.max(lchild.rmax+rchild.lmax,Math.max(lchild.max, rchild.max));
            if(lchild.lmax==lchild.rightmost-lchild.leftmost+1)
                lmax= lchild.lmax+rchild.lmax;
            else
                lmax= lchild.lmax;

            if(rchild.rmax==rchild.rightmost-rchild.leftmost+1)
                rmax= rchild.rmax+lchild.rmax;
            else    
                rmax= rchild.rmax;

        }
        public void update(int index, int newVal) {

            if (leftmost == rightmost) {

                // leaf;

                max = lmax = rmax = newVal;

            } else {

                // 2 children

                if (index <= lchild.rightmost)
                    lchild.update(index, newVal);

                else
                    rchild.update(index, newVal);

                recalc();

            }

        }

        public int[] query(int l, int r) {

            // entirely disjoint

            if (l > rightmost || r < leftmost)

                return new int[]{0,0,0};

            // covers us

            if (l <= leftmost && r >= rightmost)
                return new int[]{max,lmax,rmax};

            // we don't know
            int[] lans= lchild.query(l, r);
            int[] rans= rchild.query(l, r);
            int max1= Math.max(lans[2]+rans[1],Math.max(lans[0], rans[0]));
            int lnow,rnow=0;
            if(lans[1]==lchild.rightmost-lchild.leftmost+1)
                lnow= lans[1]+rans[1];
            else
                lnow= lans[1];

            if(rans[2]==rchild.rightmost-rchild.leftmost+1)
                rnow= rans[2]+lans[2];
            else    
                rnow= rans[2];

            return new int[]{max1, lnow,rnow};

        }

    }
