    class dsu {

        private int size;

        private int[] sz;

        private int[] par;

        private int numComponents;

        public dsu(int size) {

            this.size = numComponents = size;

            sz = new int[size];

            par = new int[size];

            clear();

        }

        public int find(int p) {

            if (p == par[p])
                return p;

            return par[p] = find(par[p]);

        }

        public void merge(int p, int q) {

            int root1 = find(p);

            int root2 = find(q);

            if (root1 == root2)
                return;

            if (sz[root2] > sz[root1]) {

                root1 ^= root2;

                root2 ^= root1;

                root1 ^= root2;

            }

            sz[root1] += sz[root2];

            par[root2] = root1;

            numComponents--;

        }

        public void clear() {

            for (int i = 0; i < size; i++) {

                par[i] = i;

                sz[i] = 1;

            }

        }

    }

