        long long total = 0;
        unordered_map<long long, long long> previousResults;
        for (int index = 0; index < size; ++index) {
            unordered_map<long long, long long> currentResults; 
            if (array[index] == target) {
                ++total;
            }
            currentResults[array[index]] = 1;
            for (auto& [value, frequency] : previousResults) {
                long long newAndResult = value & array[index];
                if (newAndResult == target) {
                    total += frequency;
                }
                currentResults[newAndResult] += frequency;
            }

            previousResults = currentResults;
        }
        return total;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& arr, int target) {
        int n = arr.size();
        long long res = 0;
        unordered_map<long long, long long> prev;

        for (int i = 0; i < n; ++i) {
            processElement(arr, target, i, res, prev);
        }

        return res;
    }

private:
    void processElement(const vector<int>& arr, int target, int idx, long long& res, unordered_map<long long, long long>& prev) {
        unordered_map<long long, long long> curr;
        long long val = arr[idx];

        if (val == target) {
            ++res;
        }

        curr[val] = 1;

        for (auto& [v, freq] : prev) {
            long long newAnd = v & val;
            if (newAnd == target) {
                res += freq;
            }
            curr[newAnd] += freq;
        }

        prev = curr;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long ans = 0;
        int i, j, l, r, m, n = nums.size(), st[200000];
        for (i = 0; i < n; i++) st[n + i] = nums[i];
        while (--i) st[i] = st[i << 1] & st[i << 1 | 1];
        for (i = j = 0; i < n; i++) {
            if ((nums[i] & k) != k) {
                j = i + 1;
                continue;
            }
            for (l = j, r = i; l < r;) {
                m = (l + r + 1) >> 1;
                if (query(st, n + m, n + i) == k) l = m;
                else r = m - 1;
            }
            if (query(st, n + l, n + i) != k) continue;
            ans += l - j + 1;
        }
        return ans;
    }

    int query(int st[], int l, int r) {
        int res = -1;
        for (r++; l < r; l >>= 1, r >>= 1) {
            if (l & 1) res &= st[l++];
            if (r & 1) res &= st[--r];
        }
        return res;
    }
};

