const int N = 1e5 + 5;
int d[N*4];
int help[N];
void build(int x, int l, int r, int n){
    if(l==r){
        if(l<=n) d[x]=help[l];
        return;
    }
    int sr=(l+r)/2;
    build(x*2, l, sr, n);
    build(x*2+1, sr+1, r, n);
    d[x]=d[x*2]&d[x*2+1];
}
int query(int x, int l, int r, int a, int b){
    if(a<=l&&r<=b){
        return d[x];
    }
    int sr=(l+r)/2;
    int res=-1;
    if(a<=sr){
        res=query(x*2, l, sr, a, b);
    }
    if(sr<b){
        int pm=query(x*2+1, sr+1, r ,a , b);
        if(res==-1) res=pm;
        else res=res&pm;
    }
    return res;
}
