        for (int i = 0; i < n; i++) spt[i][0] = nums[i];
        for (int j = 1; j < 20; j++) {
            for (int i = 0; i + (1<<j) <= n; i++) {
                spt[i][j] = spt[i][j - 1] & spt[i + (1<<(j - 1))][j - 1];
            }
        }
        function<int(int, int)> query = [&] (int l, int r) -> int {
            if (l >= r) return 0;
            int d = r - l;
            int p = 0;
            while ((1<<(p + 1)) <= d) p++;
            return spt[l][p] & spt[r - (1<<p)][p];
        };
        for (int i = 0; i < n; i++) {
            int l1 = i, r1 = n;
            while (r1 - l1 > 1) {
                int g = (l1 + r1) / 2;
                if (query(i, g) > k) l1 = g;
                else r1 = g;
            }
            if (query(i, r1) != k) continue;
            int l = i + 1, r = n;
            while (r - l > 1) {
                int g = (l + r) / 2;
                if (query(i, g) >= k) l = g;
                else r = g;
            }
            ans += r - r1;
            ans += (query(i, r) == k);
        }
        return ans;
    }
};

