class Node{
public:
	int v = (1LL<<31)-1;
	Node(){}
	Node(int val){
		v = val;
	}

	void merge(const Node& l, const Node& r){ 
		v = (l.v & r.v);
	}
};

class Update{
public:
	int v = 0;
	Update(){};
	Update(int val){
		v = val; 
	}

	void combine(const Update& otherUpdate, const int& tl, const int& tr){ 
		v += otherUpdate.v; 
	}

	void apply(Node& node, const int& tl, const int& tr) const{
		node.v += (tr - tl + 1) * v;
	}	
};

template <typename node, typename update>
class SegTree{
public:
	int len;
	vector<node> t;
	node identityElement;
	update identityTransformation; 

	SegTree(){}
	SegTree(int l){
		len = l;
		t.resize(4 * len);
		identityElement = node();
		identityTransformation = update();
	}

	template<typename T>
	void build(const T& a, int v, int tl, int tr){
		if(tl == tr){
			t[v] = a[tl];
			return;
		}
		int tm = (tl + tr)/2;
		build(a, 2*v, tl, tm);
		build(a, 2*v+1, tm+1, tr);
		t[v].merge(t[2*v], t[2*v+1]);
	}

	node query(int v, int tl, int tr, int l, int r){
		if(tl > r || tr < l) return identityElement;
		if(l <= tl && tr <= r) return t[v];
		int tm = (tl + tr)/2;
		node leftAns = query(2*v, tl, tm, l, r);
		node rightAns = query(2*v+1, tm+1, tr, l, r);
		node ans;
		ans.merge(leftAns, rightAns);
		return ans;
	}

	template<typename T>
	void build(const T& a){
		build(a, 1, 0, len-1);
	}

	node query(int l, int r){
		return query(1, 0, len-1, l, r);
	}
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        ll ans = 0;
        SegTree<Node, Update> segTree(n);
        segTree.build(nums);
        for(int i = 0; i < n; i ++) {
            int low = i, high = n - 1, idx1 = -1;
            while(low <= high) {
                int mid = low + (high - low)/2;
                int curr = segTree.query(i, mid).v;
                if(curr < k) high = mid - 1;
                else {
                    idx1 = mid;
                    low = mid + 1;
                }
            }
            low = i, high = n - 1;
            int idx2 = -1;
            while(low <= high) {
                int mid = low + (high - low)/2;
                int curr = segTree.query(i, mid).v;
                if(curr < (k + 1)) high = mid - 1;
                else {
                    idx2 = mid;
                    low = mid + 1;
                }
            }
            if(idx1 == -1) continue;
            int curr1 = segTree.query(i, idx1).v;
            if(curr1 > k) continue;
            if(idx2 == -1) idx2 = i - 1;
            // cout << idx2 << " " << idx1 << endl;
            ans += (idx1 - idx2);
        }
        return ans;
    }
};

