class SegmentTree {
private:
    vector<int> tree;
    int n;

    void buildTree(vector<int>& nums, int treeIndex, int l, int r) {
        if (l == r) {
            tree[treeIndex] = nums[l];
            return;
        }
        int mid = l + (r - l) / 2;
        buildTree(nums, 2 * treeIndex + 1, l, mid);
        buildTree(nums, 2 * treeIndex + 2, mid + 1, r);
        tree[treeIndex] = tree[2 * treeIndex + 1] & tree[2 * treeIndex + 2];
    }

    int query(int treeIndex, int start, int end, int l, int r) {
        if (l > end || r < start) return -1; 
        if (l <= start && end <= r) return tree[treeIndex];
        int mid = start + (end - start) / 2;
        int leftQuery = query(2 * treeIndex + 1, start, mid, l, r);
        int rightQuery = query(2 * treeIndex + 2, mid + 1, end, l, r);
        return leftQuery & rightQuery;
    }

public:
    SegmentTree(vector<int>& nums) {
        n = nums.size();
        tree.assign(4 * n, 0);
        buildTree(nums, 0, 0, n - 1);
    }

    int query(int l, int r) {
        return query(0, 0, n - 1, l, r);
    }
};

