#define INF INT32_MAX
#define ll long long
#define fr(i, a, b) for(int i = a; i < b; i++)
class SegmentTree {
public:
    vector<int> tree;
    int n;

    // Constructor
    SegmentTree(vector<int>& arr)
    {
        n = arr.size();
        tree.resize(4 * n);
        build(arr, 0, 0, n - 1);
    }

    // Function to build the Segment Tree
    void build(vector<int>& arr, int node, int start,
               int end)
    {
        if (start == end) {
            tree[node] = arr[start];
        }
        else {
            int mid = (start + end) / 2;
            build(arr, 2 * node + 1, start, mid);
            build(arr, 2 * node + 2, mid + 1, end);

            // bitwise AND of the children nodes
            tree[node]
                = tree[2 * node + 1] & tree[2 * node + 2];
        }
    }

    // Overloading query function to be used recursively
    int query(int l, int r)
    {
        return query(0, 0, n - 1, l, r);
    }

    // query function to get bitwise AND of the range
    int query(int node, int start, int end, int l, int r)
    {
        if (r < start || end < l) {
            return INF;
        }
        if (l <= start && end <= r) {
            return tree[node];
        }
        int mid = (start + end) / 2;
        int p1 = query(2 * node + 1, start, mid, l, r);
        int p2 = query(2 * node + 2, mid + 1, end, l, r);

        // bitwise AND operation result
        return p1 & p2;
    }
};

struct _hash {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }

    size_t operator()(uint64_t x) const {
        static const uint64_t FIXED_RANDOM = chrono::steady_clock::now().time_since_epoch().count();
        return splitmix64(x + FIXED_RANDOM);
    }
};

