class Solution {
public:

    void modify(vector<int> &bits, int n, bool add){
        int flag = add ? 1 : -1;
        for(int i=0; i<32; i++){
            bits[i] += flag*((n>>i)&1);
        }
    }

    int calAnd(vector<int> &bits, int len){
        int res = 0;
        for(int i=0; i<32; i++){
            if(bits[i]==len)res += (1ll<<i);
        }
        return res;
    }

    long long help(int lo, int hi, vector<int> &a){
        long long res= 0;
        int i=lo, j=lo;
        vector<int> bits(32,0);
        for(; j<=hi; j++){
            modify(bits,a[j],1);
            int len = j-i+1, curr = calAnd(bits, len);
            if(curr!=0)res += len;
            while(curr==0){
                // cout<<i<<" "<<j<<" "<<curr<<"\n";
                modify(bits, a[i], 0);
                i++; len--;
                curr = calAnd(bits, len);
                if(curr!=0)res+= len;
            }
        }
        long long len = hi-lo+1;
        res = (len*(len+1)/2)-res;
        return res;
    }

    long long countSubarrays(vector<int>& a, int k) {
        int n = a.size();
        long long ans = 0;
        vector<int> is(n,0);
        for(int i=0; i<n; i++){
            if((k&a[i])==k){
                is[i]=1;
                a[i]-=k;
            }
        }
        int i=0, j=0;
        for(; j<n; j++){
            if(is[j]==0){
                if(i!=j)ans += help(i,j-1,a);
                i=j+1;
            }
        }
        if(is[n-1]==1)ans+=help(i,n-1,a);
        return ans;
    }
};

class Solution {

         public long countSubarrays(int[] array, int target) {
        int size = array.length;
        long total = 0;
        Map<Long, Long> previousResults = new HashMap<>();

        for (int index = 0; index < size; ++index) {
            Map<Long, Long> currentResults = new HashMap<>();

            if (array[index] == target) {
                ++total;
            }

            currentResults.put((long) array[index], 1L);

            for (Map.Entry<Long, Long> entry : previousResults.entrySet()) {
                long value = entry.getKey();
                long frequency = entry.getValue();

                long newAndResult = value & array[index];
                if (newAndResult == target) {
                    total += frequency;
                }

                currentResults.put(newAndResult, currentResults.getOrDefault(newAndResult, 0L) + frequency);
            }

            previousResults = currentResults;
        }

        return total;
    }
}

