class Solution {
public:
    int findidx(vector<vector<int>>&countset,int k,int piv)
    {
        vector<int>tosub(30,0);
        if((piv-1)>=0)
        {
            for(int i=0;i<30;i++)
            {
                tosub[i]=countset[piv-1][i];
            }
        }
        int andvalue=0,left=piv,right=countset.size()-1;
        for(int i=0;i<30;i++)
        {
            if((countset[right][i]-tosub[i])==(right-piv+1))
            {
                andvalue|=(1<<i);
            }
        }
        if(andvalue>k)
        {
            return -1;
        }
        while(left<=right)
        {
            int mid=(left+right)/2;
            andvalue=0;
            for(int i=0;i<30;i++)
            {
                if((countset[mid][i]-tosub[i])==(mid-piv+1))
                {
                    andvalue|=(1<<i);
                }
            }
            if(andvalue>k)
            {
                left=mid+1;
            }
            else
            {
                right=mid-1;
            }
        }
        return (left);
    }
    long long ANDatmostK(int k,vector<int>&nums)
    {
        long long ans=0;
        vector<vector<int>>countset(nums.size(),vector<int>(31,0));
        for(int i=0;i<nums.size();i++)
        {
            for(int j=0;j<31;j++)
            {
                if(((1<<j)&nums[i])>0)
                {
                    countset[i][j]++;
                }
                if(i>0)
                {
                    countset[i][j]+=countset[i-1][j];
                }
            }
        }
        for(int i=0;i<nums.size();i++)
        {
            int idx=findidx(countset,k,i);
            if(idx!=(-1))
            {
                ans+=(nums.size()-idx);
            }
        }
        return ans;
    }
    long long countSubarrays(vector<int>& nums, int k) {
        return ANDatmostK(k,nums)-ANDatmostK(k-1,nums);
    }
};

