class Solution {
      public static long countSubarrays(int[] nums, int k) {
    int n = nums.length;
    long ans = 0;
    int ib = 0;
    // int x = (1 << 30) - 1 - k;
    List<Integer> zbits = new ArrayList<>();
    for (int j = 0; j < 30; j++) {
      if ((k & (1 << j)) == 0) {
        zbits.add(j);
      }
    }
    while (ib < n) {
      while (ib < n && (nums[ib] & k) != k) {
        ib++;
      }
      if (ib >= n) {
        break;
      }
      int ie = ib + 1;
      while (ie < n && (nums[ie] & k) == k) {
        ie++;
      }
      // consider [ib, ie). A qualified sub-array would contain at least one 0 for each bit
      // not set in k --- at least one 0 for each bit set in x.
      long x = func(ib, ie, nums, zbits);
      // System.out.format("  ib:%d ie:%d x:%d\n", ib, ie, x);
      ans += x;
      ib = ie;
    }
    return ans;
  }

  static long func(int l, int r, int[] nums, List<Integer> zbits) {
    int m = zbits.size();
    int[] zcnt = new int[m];
    int ie = l;
    long ans = 0;
    for (int i = l; i < r; i++) {
      while (ie < r && !isOk(zcnt)) {
        for (int j = 0; j < m; j++) {
          int h = zbits.get(j);
          if ((nums[ie] & (1 << h)) == 0) {
            zcnt[j]++;
          }
        }
        ie++;
      }
      if (!isOk(zcnt)) {
        break;
      }
      // System.out.format("    i:%d ie:%d zcnt:%s\n", i, ie, Utils.traceIn(zcnt));
      ans += r - ie + 1;
      // phase out i
      for (int j = 0; j < m; j++) {
        int h = zbits.get(j);
        if ((nums[i] & (1 << h)) == 0) {
          zcnt[j]--;
        }
      }
      // System.out.format("    i:%d ie:%d zcnt:%s\n", i, ie, Utils.traceIn(zcnt));
    }
    return ans;
  }

  static boolean isOk(int[] cnt) {
    for (int v : cnt) {
      if (v == 0) {
        return false;
      }
    }
    return true;
  }
}

