        vector<int> counts(32);
        long long ans = 0;
        for (int i = 0; i < nums.size(); i++) {
            bitset<32> nb(nums[i]);
            // Update count
            for (int i = 0; i < 32; i++) {
                if (nb[i]) {
                    counts[i]++;
                } else {
                    counts[i] = 0;
                }
            }

            int minKLen = i + 1;
            int maxNonKLen = 0;
            for (int i = 0; i < 32; i++) {
                if (kb[i]) {
                    minKLen = min(minKLen, counts[i]);
                } else {
                    maxNonKLen = max(maxNonKLen, counts[i]);
                }
            }
            if (minKLen > maxNonKLen)
                ans += minKLen - maxNonKLen;
        }
        return ans;
    }
