class Solution {
public:
    long long countSubarrays(vector<int>& v, int k) {
        int p=30;
        int n=v.size();
        int dp[n+1][p+1];
        for(int j=0;j<=p;j++){
            dp[0][j]=0;
        }
        for(int i=1;i<=n;i++){
            for(int j=0;j<=p;j++){
                if((1<<j)&v[i-1]){
                    dp[i][j]=dp[i-1][j];
                }
                else{
                    dp[i][j]=i;
                }
            }
        }




        ll ans=0;
        for(int i=1;i<=n;i++)
        {


            ll ln=0;
            int t=1;
            for(int j=0;j<=p;j++){
                if((1<<j)&k){
                    if(!( (1<<j)&v[i-1] )){t=0;break;}
                    ln=max(ln,(ll)dp[i][j]+1);
                }
            }
            ln=i-ln+1;
            ln=min(ln,(ll)i);
            if(!t){
                continue;
            }





            // now check the non-caring 1s range and find the min-of them():
            ll zr=ln;
            for(int j=0;j<=p;j++){
                if(!((1<<j)&k)){  //non-caring:
                    if(!( (1<<j)&v[i-1] )){continue;}

                        ll pos=dp[i][j];
                        pos++;
                        ll len=(i-pos+1);
                        if(len>ln){t=0;break;}
                        zr=min(zr,ln-len);

                }
            }
            if(t){
                ans+=zr;
            }

        }
        return ans;


    }
};

