class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        def get_bits(num: int) -> List[int]:
            return [bool((2 ** bit) & num) for bit in range(33)]

        missing_bit_to_last_pos = defaultdict(lambda: -1)
        start = 0
        res = 0
        for pos, num in enumerate(nums):
            if (num & k) != k:
                start = pos + 1
                continue
            end = pos
            for i, bit in enumerate(get_bits(num ^ k)):
                if not bit:
                    continue
                if missing_bit_to_last_pos[i] < start:
                    end = start - 1
                else:
                    end = min(end, missing_bit_to_last_pos[i])

            for i, bit in enumerate(get_bits(num)):
                if not bit:
                    missing_bit_to_last_pos[i] = pos
            res += end + 1 - start 
        return res

