class Solution {
public:
    #define int long long
    #define MAX 100000
    #define bitscount 32

    // Array to store bit-wise
    // prefix count
    int prefix_count[bitscount][MAX];

    // Function to find the prefix sum
    void findPrefixCount(vector<int> &arr, int n)
    {

        // Loop for each bit
        for (int i = 0; i < bitscount; i++) {

            // Loop to find prefix count
            prefix_count[i][0] = ((arr[0] >> i) & 1);
            for (int j = 1; j < n; j++) {
                prefix_count[i][j] = ((arr[j] >> i) & 1);
                prefix_count[i][j] += prefix_count[i][j - 1];
            }
        }
    }

    // Function to answer query
    int rangeAnd(int l, int r)
    {

        // To store the answer
        int ans = 0;

        // Loop for each bit
        for (int i = 0; i < bitscount; i++) {
            // To store the number of variables
            // with ith bit set
            int x;
            if (l == 0)
                x = prefix_count[i][r];
            else
                x = prefix_count[i][r]
                    - prefix_count[i][l - 1];

            // Condition for ith bit
            // of answer to be set
            if (x == r - l + 1)
                ans = (ans | (1 << i));
        }

        return ans;
    }
    int solve(vector<int> &arr,int k)
    {
        int ans=0;
        int n=arr.size();
        findPrefixCount(arr,n);
        for(int i=0;i<n;i++)
        {
            int lo=i;
            int hi=n-1;
            int first=n;
            int last=-1;
            while(lo<=hi)
            {
                int mid=(lo+hi)/2;
                int val=rangeAnd(i,mid);
                if(val>k)
                {
                    lo=mid+1;
                }
                else if(val<=k)
                {
                    if(val==k)
                    {
                        first=min(first,mid);
                    }
                    hi=mid-1;
                }
            }
            lo=i;
            hi=n-1;
            while(lo<=hi)
            {
                int mid=(lo+hi)/2;
                int val=rangeAnd(i,mid);
                if(val>=k)
                {
                    lo=mid+1;
                    if(val==k)
                    {
                        last=max(last,mid);
                    }
                }
                else if(val<k)
                {
                    hi=mid-1;
                }
            }
            if(last==-1)
            {
                continue;
            }
            ans=ans+last-first+1;
        }
        return ans;
    }
    #undef int
    long long countSubarrays(vector<int>& nums, int k) {
        vector<long long> arr(nums.begin(),nums.end());
        return solve(arr,k);
}
};

