#define ll int
class SegmentTree {
public:
    vector<int> tree;
    ll n;
    SegmentTree(vector<ll>& arr)
    {
        n = arr.size();
        tree.resize(4 * n);
        build(arr, 0, 0, n - 1);
    }

    void build(vector<ll>& arr, ll node, ll start,
               ll end)
    {
        if (start == end) {
            tree[node] = arr[start];
        }
        else {
            ll mid = (start + end) / 2;
            build(arr, 2 * node + 1, start, mid);
            build(arr, 2 * node + 2, mid + 1, end);
            tree[node] = tree[2 * node + 1] & tree[2 * node + 2];
        }
    }

    ll query(ll l, ll r)
    {
        return query(0, 0, n - 1, l, r);
    }

    ll query(ll node, ll start, ll end, ll l, ll r)
    {
        if (r < start || end < l) {
            return INT_MAX;
        }
        if (l <= start && end <= r) {
            return tree[node];
        }
        ll mid = (start + end) / 2;
        ll p1 = query(2 * node + 1, start, mid, l, r);
        ll p2 = query(2 * node + 2, mid + 1, end, l, r);

        return p1 & p2;
    }
};
class Solution {
