        SegmentTree tr(nums);
        return solveK(nums,k,tr) - solveK(nums,k-1,tr);
    }
};

class Solution {

    public long Solve(int s, int e, int [][] prefix, int k){
        int ptr=s;
        int st = s;
        long rem = 0l;
        while(ptr<e){
            boolean found = false;
            int gap = ptr-st+1;
            for(int j=0;j<31;j++){
                if(((1<<j) & k) != 0) continue;
                int freq = prefix[ptr][j] - (st==0?0:prefix[st-1][j]);

                if(freq == gap) {
                    ptr++;
                    found = true;
                    break;
                }
            }

            if(!found){
                st++;
            } else {
                rem += gap;
            }
        }
        return rem;
    }
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        int [][] prefix = new int [n][31];
        long ans = 0l;
        for(int i=0;i<n;i++){
            for(int j=0;j<31;j++){
                if(((1<<j)&nums[i]) != 0){
                    prefix[i][j]=1+(i==0?0:prefix[i-1][j]);
                } else {
                    prefix[i][j] = (i==0?0:prefix[i-1][j]);
                }
            }
        }

        for(int i=0;i<n;i++){
            if((nums[i]&k) != k){
                continue;
            }
            int ptr=i;
            while(ptr < n){
                if((nums[ptr]&k)==k){
                    ptr++;
                } else {
                    break;
                }
            }
            int gap = ptr-i;
            ans += (gap*(gap+1l))/2l;
            int x=i;

            ans -= Solve(i, ptr, prefix, k);
            i=ptr-1;
        }

        return ans;
    }
}

