class Solution {
    static int MAX = 100000;
static int bitscount =32;

static int [][]prefix_count = new int [bitscount][MAX];

static void findPrefixCount(int arr[], int n)
{

    for (int i = 0; i < bitscount; i++) 
    {

        prefix_count[i][0] = ((arr[0] >> i) & 1);
        for (int j = 1; j < n; j++) 
        {
            prefix_count[i][j] = ((arr[j] >> i) & 1);
            prefix_count[i][j] += prefix_count[i][j - 1];
        }
    }
}


static int rangeAnd(int l, int r)
{
    int ans = 0;
    for (int i = 0; i < bitscount; i++) 
    {

        int x;
        if (l == 0)
            x = prefix_count[i][r];
        else
            x = prefix_count[i][r]
                - prefix_count[i][l - 1];


        if (x == r - l + 1)
            ans = (ans | (1 << i));
    }

    return ans;
}
    public long countSubarrays(int[] nums, int k) {
        long ans=0;
        findPrefixCount(nums, nums.length);
        for(int j=0;j<nums.length;j++)
        {
            int l=j;
            int r=nums.length-1;
            int first=-1;
            int last=-1;
            while(l<=r)
            {
                int mid=l+(r-l)/2;
                int currand=rangeAnd(j,mid);
                if(currand>k)
                    l=mid+1;
                else if(currand==k)
                {
                    first=mid;
                    r=mid-1;
                }
                else
                    r=mid-1;
            }
            l=j;
            r=nums.length-1;
            while(l<=r)
            {
                int mid=l+(r-l)/2;
                int currand=rangeAnd(j,mid);
                if(currand>k)
                    l=mid+1;
                else if(currand==k)
                {
                    last=mid;
                    l=mid+1;
                }
                else
                    r=mid-1;
            }
            if(first!=-1)
                ans+=last-first+1;
        }
        return ans;
    }
}

