struct segtree {
    ll size = 1LL;
    v64 sums;

    void init(ll n) {
        while (size < n) size *= 2;
        // size > n and power of 2
        sums.assign(2 * size, LLONG_MAX);
    }

    void set(ll i, ll v, ll x, ll lx, ll rx) {
        if (rx - lx == 1) {
            sums[x] = v;
            return;
        }

        ll mid = (lx + rx) / 2;
        if (i < mid) {
            set(i, v, 2 * x + 1, lx, mid);
        } else {
            set(i, v, 2 * x + 2, mid, rx);
        }

        sums[x] = sums[2*x + 1] & sums[2*x + 2];

    }

    void set(ll i, ll v) {
        set(i, v, 0, 0, size);
    }

    ll sum(ll l, ll r, ll x, ll lx, ll rx) {
        if (lx >= r || l >= rx) return LLONG_MAX;
        if (l <= lx && rx <= r) return sums[x];

        ll mid = (lx + rx) / 2;
        ll s = (
            sum(l, r, 2 * x + 1, lx, mid) & 
            sum(l, r, 2 * x + 2, mid, rx)
        );
        return s;
    }

    ll sum(ll l, ll r) {
        return sum(l, r, 0, 0, size);
    }
};


class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        ll n = (ll)(nums.size());
        ll ans = 0ll;

        segtree st;
        st.init(n);

        forn(i, n) st.set(i, nums[i]);
        // cout << st.sum(0, sz(nums)) << "\n";

        forn(i, n) {
            if (nums[i] < k) continue;
            if (st.sum(i, n) > k) continue;
            auto rp = n;
            auto lp = i;
            // st.sum(i, n) <= k

            while (lp + 1 < rp) {
                auto mid = lp + (rp - lp) / 2;
                auto v = st.sum(i, mid+1);
                if (v < k) {
                    rp = mid;
                } else {
                    lp = mid;
                }
            }
            auto ub = lp;
            if (st.sum(i, ub+1) != k) continue;
            if (nums[i] == k) {
                ans += ub - i + 1;
            } else {

                lp = i;
                rp = n;
                while (lp + 1 < rp) {
                    auto mid = lp + (rp - lp) / 2;
                    auto v = st.sum(i, mid+1);
                    if (v <= k) {
                        rp = mid;
                    } else {
                        lp = mid;
                    }
                }
                // v[rp] <= k
                // v[lp] > k
                auto lb = lp;
                ans += (ub - lb); 
            }
        }
        return ans;
    }
};

