class Solution {
public:
    #define ll long long
    long long countSubarrays(vector<int>& a, int k) {
        int n = a.size();
        vector<vector<int>> spTable(n, vector<int>(22));
        sparseBuild(spTable, a);

        long long ans = 0;

        for(int i = 0; i < n; i++) {
            int low = 0, high = i, id = -1;
            while(low <= high) {
                int mid = (low + high) / 2;
                int val = sparseQuery(spTable, mid, i);
                if(val >= k) {
                    id = mid;
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            }

            if(id == -1) continue;
            if(sparseQuery(spTable, id, i) != k) continue;
            int left = id;

            low = id;
            high = i;
            id = -1;
            while(low <= high) {
                int mid = (low + high) / 2;
                int val = sparseQuery(spTable, mid, i);
                if(val > k) {
                    id = mid;
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            }
            if(id == -1) id = i + 1;
            int right = id;

            ans += (right - left);
        }

        return ans;
    }

    void sparseBuild(vector<vector<int>>& spTable, vector<int>& a) {
            ll n = a.size();
            int L = 22;
            for(ll i = 0; i <= n - 1; i++) spTable[i][0] = a[i];
            for(ll j = 1; j < L; j++) {
                    for(ll i = 0; i + (1LL << j) <= (n - 1) + 1; i++) {
                            spTable[i][j] = (spTable[i][j - 1] & spTable[i + (1LL << (j - 1))][j - 1]);
                    }
            }
    }

    ll lg(ll x) {
            return (32 - __builtin_clz(x) - 1);
    }

    ll sparseQuery(vector<vector<int>>& spTable, ll l, ll r) {
            ll k = lg(r - l + 1);
            return (spTable[l][k] & spTable[r - (1LL << k) + 1][k]);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& array, int target) {
