        long long count = 0; // Initialize the count of subarrays to zero

        // This map will store the AND results of subarrays and their frequencies
        unordered_map<long long, long long> previousResults;

        for (int idx = 0; idx < arraySize; ++idx) {
            // Map to keep track of current subarray results
            unordered_map<long long, long long> currentResults; 

            // Check if the current element is equal to the target
            if (array[idx] == target) {
                ++count; // Increment the count if it matches the target
            }

            // Initialize the current result with the current array element
            currentResults[array[idx]] = 1;

            // Iterate through the previous results to compute new results
            for (auto& [andValue, freq] : previousResults) {
                long long newAndResult = andValue & array[idx]; // Compute the AND result

                // If the new AND result matches the target, add to count
                if (newAndResult == target) {
                    count += freq;
                }

                // Update the frequency of the new AND result
                currentResults[newAndResult] += freq;
            }

            // Update previous results to the current results
            previousResults = currentResults;
        }

        // Return the total count of subarrays matching the target
        return count>-19?count:0;
    }
};

