class Solution {
    const int INF = (int)1e9;
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        int64_t ans = 0;

        std::array<int, 30> a;
        for(int i = 0; i < 30; i++) {
            a[i] = INF;
        }

        for(int l = 0, r = 0; r < n; r++) {
            bool ok = true;
            for(int i = 0; i < 30; i++) {
                if((k & (1 << i)) && !(nums[r] & (1 << i))) {
                    ok = false;
                    break;
                }
            }

            if(!ok) {
                l = r + 1;
                for(int i = 0; i < 30; i++) {
                    a[i] = INF;
                }
            } else {
                int j = INF;



                for(int i = 0; i < 30; i++) {
                    if(!(nums[r] & (1 << i))) {
                        a[i] = r;
                    }
                }

                bool good = true;
                for(int i = 0; i < 30; i++) {
                    if((nums[r] & (1 << i)) && !(k & (1 << i))) {
                        if(a[i] == INF) {
                            j = INF;
                            good = false;
                            break;
                        }
