class Solution {
    using num_t = long long;
    using idx_t = int;
    using map_t = unordered_map<num_t, idx_t>;
    static constexpr int max_num = 1e9;
    bool hasEssentialBits(num_t num, num_t k){
        for(num_t mask = 1; mask <= max_num; mask <<= 1){
            if((k & mask) && !(num & mask)){ return false; }
        }
        return true;
    }

    void lastZeros(map_t & last_zeros, num_t num, num_t idx){
        for(num_t mask = 1; mask <= max_num; mask <<= 1){
            if((num & mask) == 0){ last_zeros[mask] = idx; }
        }
    }

    idx_t lastValid(map_t & last_zeros, num_t k, idx_t r){
        idx_t l = r;
        for(num_t mask = 1; mask <= max_num; mask <<= 1){
            if((k & mask) == 0){
                l = min(l, last_zeros[mask]);
            }
        }
        return l;
    }

public:
    long long countSubarrays(vector<int>& nums, int k) {
        const idx_t n = nums.size();
        long long ans = 0;
        map_t last_zeros;
        for(num_t mask = 1; mask <= max_num; mask <<= 1){
            last_zeros[mask] = -1;
        }

        for(idx_t l=0, r=0; r<n; r++){
            const num_t num = nums[r];
            // cout << bitset<8>(num) << ": ";
            if(!hasEssentialBits(num, k)){ l = r+1; continue; }

            lastZeros(last_zeros, num, r);
            // for(auto [m, x]: last_zeros){ cout << x << " "; } cout << endl;

            idx_t l_ = lastValid(last_zeros, k, r);
            // cout << l << " " << l_ << endl;
            if(l_ >= l){
                ans += l_ - l + 1;
            }    
        }
        // cout <<endl;
        return ans;
    }
};

