                    {
                        bits[i]--;
                        // if(bits[i]==0)
                        // {
                        //     curr=(curr&~(1<<(i)));
                        // }
                    }
                    else if(bits[i]==(right-left))
                    {
                        curr=(curr|(1<<i));
                    }
                }
                left++;
            }
            if(left>right)
            {
                curr=-1;
            }
            count+=(right-left+1);
        }
        return count;
    }
    ll subarrayANDLesserThanK(vector<int>& nums, int k)
    {
