class seg_tree{
		public:
vector<int>seg;
seg_tree(int n)
{
		seg.resize(4*n+1);
}
void build(int ind,int low,int high,vector<int>&arr)
{
		if(low==high)
		{
				seg[ind]=arr[low];
				return;
		}
		int mid=(low+high)/2;
		build(2*ind+1,low,mid,arr);
		build(2*ind+2,mid+1,high,arr);
		seg[ind]=seg[2*ind+1]&seg[2*ind+2];
}
int query(int ind,int low,int high,int l,int r)
{
		if(r<low || l>high)return INT_MAX;
		if(low>=l && high<=r)return seg[ind];
		int mid=(low+high)>>1;
		int left=query(2*ind+1,low,mid,l,r);
		int right=query(2*ind+2,mid+1,high,l,r);
		return left&right;
}
void update(int ind,int low,int high,int i,int val)
{
		if(low==high)
		{
				seg[ind]=val;
				return;
		}
		int mid =(low+high)>>1;
		if(i<=mid)update(2*ind+1,low,mid,i,val);
		else
		update(2*ind+2,mid+1,high,i,val);

		seg[ind]=min(seg[2*ind+1],seg[2*ind+2]);
}
};
class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
				long long ans=0;
				seg_tree s(n);
				s.build(0,0,n-1,nums);
				for(int i=0;i<n;i++)
				{
						int l=i;
						int h=n-1;
						int ind1=n;
						int ind2=n;
						while(l<=h)
						{
							int mid=(l+h)/2;
							if(s.query(0,0,n-1,i,mid)>(k-1)){
								l=mid+1;
							}
							else
							{
								ind1=mid;
								h=mid-1;
							}
						}
						l=i;
						h=n-1;
						while(l<=h)
						{
							int mid=(l+h)/2;
							if(s.query(0,0,n-1,i,mid)>k){
								l=mid+1;
							}
							else
							{
								ind2=mid;
								h=mid-1;
							}
						}
						ans+=1LL*(ind1-ind2);
				}
				return ans;

    }
};

