using i64 = int64_t;
struct tree_t
{
    vector<i64> a;
    int nn;
    tree_t(int n): a(n*4, ~i64(0))
    {
        for(nn=1;nn<n;nn*=2);
    }
    void modify(int l,int r,int q,int val, int v)
    {
        if(l+1==r)
        {
            a[v] = val;
            return;
        }
        int m = (l+r)/2;
        int lc = 2*v;
        int rc = 2*v+1;
        if(q<m)
        {
            modify(l,m,q,val,lc);
        }
        else
        {
            modify(m,r,q,val,rc);
        }
        a[v] = a[lc] & a[rc];
    }
    void modify(int q,int val)
    {
        modify(0, nn, q, val, 1);
    }
    i64 query(int l,int r, int ql,int qr,int v) const
    {
        if(ql<=l && r<=qr)
        {
            return a[v];
        }
        int m = (l+r)/2;
        int lc = 2*v;
        int rc = 2*v+1;
        i64 ans = ~i64(0);
        if(ql < m)
        {
            ans &= query(l,m,ql,qr,lc);
        }
        if(m < qr)
        {
            ans &= query(m,r,ql,qr,rc);
        }
        return ans;
    }
    i64 query(int ql,int qr) const
    {
        return query(0, nn, ql, qr, 1);
    }
};
