        // 0 0 0 1 1 1 0 1 0
        // 1 2 3 3 3 3 4 4 5
        // 3 * 4 / 2 + 1 * 2 / 2 + 0 * 1 /2

        // k = 0
        // 0 0 0 1 1 1 0 1 0
        // 1 2 3 3 3 3 4 4 5
        // all pairs - the answer above

        // Andsum of [l, r] = nums[l] & nums[l+1] ... & nums[r]
        // Andsum of [l+1, r] >= Andsum of [l, r] >= Andsum of [l, r+1]
        // for each l, we find the r1 such that Andsum(l, r1-1) > k and Andsum(l, r1) == k
        //                     the r2 such that Andsum(l, r2) == k and Andsum(l, r2+1) < k
        // with binary search and calulate Andsum(l, r) with segment tree

        i64 n = nums.size();
        tree_t tree(n);
        for(int i=0;i<n;++i)
        {
            tree.modify(i, nums[i]);
        }
        vector<int> index(n);
        iota(index.begin(), index.end(), 0);
        i64 ans = 0;
        for(i64 l = 0;l < n;++l)
        {
            if(nums[l] < k)
            {
                continue;
            }
            // for(int r = l; r< n;++r)
            // {
            //     cout << "123:" << l << " " << r<<" " << tree.query(l, r+1) << "\n";
            // }
            auto comp = [&l,&tree, &k](int v, const vector<int>&){
                return tree.query(l, v+1) > k;
            };
            auto comp2 = [&l,&tree, &k](const vector<int>&, int v){
                return k > tree.query(l, v+1);
            };
            auto lt = std::lower_bound(index.begin()+l, index.end(), vector<int>{}, comp);
            auto rt = std::upper_bound(index.begin()+l, index.end(), vector<int>{}, comp2);
            // cout << l << " " << lt - index.begin() << " " << rt - index.begin() << "\n";
            ans += rt - lt;
        }
        return ans;
    }
};

