// segtree with one-based indexing
//
// build:
//    SegTree<int> seg;
//    seg.build(a); // vector `a` must be one-indexed
// 
// update:
//    seg.update(pos, inc); //increase a[pos] to a[pos] + inc
//    //you may want to set this
// query:
//    seg.query(l, r)

template<class T>
struct SegTree {
  vector<T> st;
  int n;
  SegTree(int _n) : n(_n) {
    T default_value = 0;
    st.assign(4 * n, default_value);
  }
  void build(const vector<T> &a) {
    build(a, 1, 1, n);
  }
  void build(const vector<T>& a, int id, int l, int r) {
    if(l == r) {
      st[id] = a[l];
      return;
    }
    int mid = (l + r) >> 1;
    build(a, id * 2, l, mid);
    build(a, id * 2 | 1, mid + 1, r);
    st[id] = st[id * 2] & st[id * 2 | 1];
  }
  void update(int pos, T inc) {
    update(pos, inc, 1, 1, n);
  }
  void update(int pos, T inc, int id, int l, int r) {
    if(pos < l || r < pos) {
      return;
    }
    if(l == r) {
      st[id] += inc;
      return;
    }
    int mid = (l + r) >> 1;
    update(pos, inc, id * 2, l, mid);
    update(pos, inc, id * 2 | 1, mid + 1, r);
    st[id] = st[id * 2] & st[id * 2 | 1];
  }
  T query(int u, int v) {
    return query(u, v, 1, 1, n);
  }
  T query(int u, int v, int id, int l, int r) {
    if(v < l || r < u) {
      return (1ll << 30) - 1;
    }
    if(u <= l && r <= v) {
      return st[id];
    }
    int mid = (l + r) >> 1;
    return query(u, v, id * 2, l, mid) & query(u, v, id * 2 | 1, mid + 1, r);
  }
};

class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        long long ans = 0, n = a.size();
        a.insert(a.begin(), 0);
        SegTree<int> st(n);
        st.build(a);
        for (int i = 1; i <= n; i++) {
            int l = 1, r = i;
            int br = -1;
            while (l <= r) {
                int m = (l + r) >> 1;
                int val = st.query(m, i);
                // cout << "val : " << val << " m i: " << m << ' ' << i << '\n';
                if (val > k) {
                    r = m - 1;
                } else {
                    l = m + 1;
                    if (val == k) {
                        if (br == -1) {
                            br = m;
                        } else {
                            br = max(br, m);
                        }
                    }
                }
            }
            l = 1;
            r = i;
            int bl = -1;
            while (l <= r) {
                int m = (l + r) >> 1;
                int val = st.query(m, i);
                if (val >= k) {
                    r = m - 1;
                    if (val == k) {
                        if (bl == -1) {
                            bl = m;
                        } else {
                            bl = min(bl, m);
                        }
                    }
                } else {
                    l = m + 1;
                }
            }
            if (bl == -1 || br == -1) {
                continue;
            }
            int curr = br - bl + 1;
            // cout << "curr: " << curr << '\n';

            ans += curr;
        }
        return ans;
    }
};

