class Solution {
    public long countSubarrays(int[] nums, int k) {
         int n = nums.length;
        long totalSubarrays = 0;
        Map<Long, Long> bitwiseAndFrequency = new HashMap<>();  // Map to track frequency of AND results

        for (int i = 0; i < n; ++i) {
            Map<Long, Long> newFrequencyMap = new HashMap<>();  // Map for storing updated frequencies for this iteration

            // If the current number equals the target, count it as a valid subarray
            if (nums[i] == k) {
                ++totalSubarrays;
            }

            // Update the new frequency map with the current number
            newFrequencyMap.put((long) nums[i], 1L);

            // Process previous results to update the total subarrays count
            for (Map.Entry<Long, Long> entry : bitwiseAndFrequency.entrySet()) {
                long andResult = entry.getKey();
                long count = entry.getValue();
                long newAndResult = andResult & nums[i];  // Perform bitwise AND operation
                if (newAndResult == k) {
                    totalSubarrays += count;  // Add the count of subarrays where AND result equals the target
                }
                newFrequencyMap.put(newAndResult, newFrequencyMap.getOrDefault(newAndResult, 0L) + count);  // Update the frequency map
            }

            // Update the bitwise AND frequency map with new results
            bitwiseAndFrequency = newFrequencyMap;
        }

        return totalSubarrays; 
    }
}

