class Solution {
public:
    typedef long long ll; 

struct item {
    ll ac;
};

struct sparseTable {
    ll sze;
    ll mxlog;
    vector<ll> logval;
    vector<vector<item>> table;

    item merge(item a, item b) { // min, max, gcd
        return {a.ac&b.ac};
    }

    item single(ll v) {
        return {v};
    }

    void build(vector<ll> &a) {
        sze = a.size();
        mxlog = log2(sze);
        table.resize(sze + 1);
        logval.resize(sze + 1);

        logval[1] = 0;
        for (ll i = 2; i <= sze; ++i) {
            logval[i] = logval[i / 2] + 1;
        }

        for (ll i = 0; i < sze; ++i) {
            table[i].resize(mxlog + 1);
            fill(table[i].begin(), table[i].end(), item());
        }

        for (ll i = 0; i < sze; i++) {
            table[i][0] = single(a[i]);
        }
        for (ll i = 1; i <= mxlog; i++) {
            for (ll j = 0; (j + (1 << i)) <= sze; j++) {
                table[j][i] = merge(table[j][i - 1], table[j + (1 << (i - 1))][i - 1]);
            }
        }
    }

    item query(ll l, ll r) {
        ll j = logval[r - l + 1];
        item ans = item();
        ans = merge(table[l][j], table[r - (1 << j) + 1][j]); // O(1)
        return ans;
    }
};



    ll cnt(vector<int> &v, int k, int l, int r, sparseTable &st){

        ll res=-1, idx=l;
        while(l<=r){
            ll mid=l+(r-l)/2;
            ll val=st.query(idx, mid).ac;
            // cout << l << " " << mid << " " << r << " " << val << endl;
            if(val>=k){
                res=max(res, mid);
                l=mid+1;
            }else r=mid-1;
        }
        // cout << res << endl;
        if(res==-1)return 0;
        return res-idx+1;
    }


    long long countSubarrays(vector<int>& nums, int k) {
        vector<ll> v;
        for(auto x: nums)v.push_back(x);
        sparseTable st;
        st.build(v);
        ll res=0, n=nums.size();
        for(int i=0; i<n; i++){
            ll r = cnt(nums, k, i, n-1, st), l = cnt(nums, k+1, i, n-1, st);
            // cout << l << " " << r << " " << i << endl;
            ll cur=r-l;
            res+=cur;
        }
        return res;
    }
};

class Solution {
public:
    class SegTree {
        vector<int> seg;

    public:
        SegTree(int n) { seg.resize(4 * n + 1, INT_MAX); }
        void build(int ind, int low, int high, vector<int>& arr) {
            if (low == high) {
                seg[ind] = arr[low];
                return;
            }
            int mid = (low + high) / 2;
            build(2 * ind + 1, low, mid, arr);
            build(2 * ind + 2, mid + 1, high, arr);
            seg[ind] = seg[2 * ind + 1] & seg[2 * ind + 2];
        }
        int query(int ind, int low, int high, int l, int r) {
            // no overlap
            // l r low high || low high l r
            if (l > high || r < low) {
                return INT_MAX;
            }
            // complete overlap
            // l low high r
            if (l <= low && r >= high) {
                return seg[ind];
            }
            // partial overlap
            int mid = (low + high) / 2;
            int left = query(2 * ind + 1, low, mid, l, r);
            int right = query(2 * ind + 2, mid + 1, high, l, r);
            return left & right;
        }
        void update(int ind, int low, int high, int i, int val,
                    vector<int>& arr) {
            if (low == high) {
                seg[ind] = val;
                arr[i] = val;
                return;
            }
            int mid = (low + high) / 2;
            if (i <= mid) {
                update(2 * ind + 1, low, mid, i, val, arr);
            } else {
                update(2 * ind + 2, mid + 1, high, i, val, arr);
            }
            seg[ind] = seg[2 * ind + 1] & seg[2 * ind + 2];
        }
    };
    long long countSubarrays(vector<int>& nums, int k) {
        SegTree st(nums.size());
        st.build(0, 0, nums.size() - 1, nums);
        int n = nums.size();
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int lo = i - 1, hi = n - 1;
            while (hi - lo > 1) {
                int mid = (lo + hi) / 2;
                int val = st.query(0, 0, n - 1, i, mid);
                if (val > k) {
                    lo = mid;
                } else {
                    hi = mid;
                }
            }
            if (st.query(0, 0, n - 1, i, hi) == k) {
                int lo1 = hi - 1, hi1 = n;
                while (hi1 - lo1 > 1) {
                    int mid = (lo1 + hi1) / 2;
                    int val = st.query(0, 0, n - 1, i, mid);
                    if (val >= k) {
                        lo1 = mid;
                    } else {
                        hi1 = mid;
                    }
                }
                //cout << hi1 << " " << lo1 << " " << hi << endl;
                if (st.query(0, 0, n - 1, i, lo1) == k) {
                    ans += max(0, min(n - 1, lo1) - max(0,hi) + 1);
                } else {
                    ans += 1;
                }
            }
        }
        return ans;
    }
};

