class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long res = 0;
        vector<int> bits(32, 0);
        int l=-1;
        int r=-1;
        int cur = k;
        bool reset = false;

        for (int i=0; i<nums.size(); ++i) {
            if ((nums[i] & k) != k)
            {
                if (reset)
                {
                    l = r = -1;
                    resetBits(bits);
                    reset = false;
                }
            } else {
                int n = l == -1 ? 1 : (i - r + 1);
                reset = true;
                cur = andV(bits, nums[i], n);
                if (cur != k) {
                    if (l == -1) {
                        l = r = i;
                    }
                } else {
                    if (l == -1)
                        l = r = i;

                    while (r < i) {
                        cur = remove(bits, nums[r], --n);
                        if (cur != k) {
                            cur = andV(bits, nums[r], ++n);
                            break;
                        }

                        r++;
                    }

                    res += r - l + 1;
                }
                // cout << res << " " << l << " " << r << " " << i << " " << cur << " " << n << endl;
            }

        }

        return res;
    }

    void resetBits(vector<int>& bits) {
        for (auto& i: bits)
            i = 0;
    }

    int remove(vector<int>& bits, int val, int n) {
        int res = 0;
        for (int i=0; i<32; ++i) {
            int mask = 1 << i;
            if (val & mask) {
                bits[i]--;
            }

            if (bits[i] == n)
                res |= mask;
        }

        return res;
    }

    int andV(vector<int>& bits, int val, int n) {
        int res = 0;
        for (int i=0; i<32; ++i) {
            int mask = 1 << i;
            if (val & mask)
            {
                bits[i]++;
                if (bits[i] == n)
                    res |= mask;
            }
        }

        return res;
    }
};

