#define ll long long

class SegmentTree {
private:
    vector<int> tree;
    int n;

    void buildTree(const vector<int>& arr, int start, int end, int node) {
        if (start == end) {
            tree[node] = arr[start];
        } else {
            int mid = (start + end) / 2;
            buildTree(arr, start, mid, 2 * node + 1);
            buildTree(arr, mid + 1, end, 2 * node + 2);
            tree[node] = (tree[2 * node + 1]& tree[2 * node + 2]);
        }
    }

    void updateTree(int start, int end, int index, int value, int node) {
        if (start == end) {
            tree[node] = value;
        } else {
            int mid = (start + end) / 2;
            if (index <= mid) {
                updateTree(start, mid, index, value, 2 * node + 1);
            } else {
                updateTree(mid + 1, end, index, value, 2 * node + 2);
            }
            tree[node] = (tree[2 * node + 1]& tree[2 * node + 2]);
        }
    }

    ll queryTree(int start, int end, int l, int r, int node) {
        if (l <= start && r >= end) {
            return (long long)tree[node];
        }
        if (end < l || start > r) {
            return (long long)(1ll<<32)-1;
        }
        int mid = (start + end) / 2;
        return (queryTree(start, mid, l, r, 2 * node + 1)&
                   queryTree(mid + 1, end, l, r, 2 * node + 2));
    }

public:
    SegmentTree(const vector<int>& arr) {
        n = arr.size();
        tree.resize(4 * n);
        buildTree(arr, 0, n - 1, 0);
    }

    void update(int index, int value) {
        updateTree(0, n - 1, index, value, 0);
    }

    ll query(int l, int r) {
        return queryTree(0, n - 1, l, r, 0);
    }
};


class Solution {
public:

    long long countSubarrays(vector<int>& nums, int k) {
