class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
        int pre[30][n+1];
        memset(pre,0,sizeof(pre));
        for(int i=0;i<30;i++){
            for(int j=1;j<=n;j++){
                pre[i][j]=pre[i][j-1]+((nums[j-1] & (1<<i)) > 0);
            }
        }
        long long ans=0;
        for(int j=0;j<n;j++){
            int l=j+1,r=n;
            for(int i=0;i<30;i++){
                int mask=(1<<i);
                int low=j,high=n+1;
                while(high-low > 1){
                    int mid=low+(high-low)/2;
                    if(pre[i][mid]-pre[i][j] < mid-j) high=mid;
                    else low=mid;
                }
                if((k&mask) == 0) l=max(l,high);
                else r=min(r,low);
            } 
            ans+=max(0,r-l+1);
        }
        return ans;
    }
};

